  "checklist_alignment": {
    "next_incomplete_stage": "3. Prepare classification passages and design the analysis.",
    "immediate_work": [
      "Sample representative conversations to discover question and context types.",
      "Prioritize answerable questions and practical outputs; populate the analysis matrix.",
      "Keep the user, people discussed, interactions, and ChatGPT as distinct analytical subjects.",
      "Establish comparison periods from available dates.",
      "Design conversations-to-exchanges-to-passages organization, references, context windows, branches, and a passage-size pilot."
    ],
    "preceding_stage_status": "Stage 2 extraction is marked complete in CHECKLIST.md. The repository directory contains the 14 extracted conversation shards (conversations-000.json through conversations-013.json), export_manifest.json, shard_batches.json, and key_type_inventory.json."
  },
  "adequacy_assessment": {
    "current_plan_sufficient": false,
    "reason": "The prior plan includes many conversation settings but does not specify how Stage 3 will inspect ordered exchanges, preserve branch/message references, or access representative source text. Metadata keys alone cannot reveal question/context types or support passage-boundary decisions."
  },
  "capture_for_stage3": {
    "conversation_index": [
      {
        "key": "id",
        "observed_types": [
          "string"
        ],
        "purpose": "Stable conversation reference; preserve separately from conversation_id."
      },
      {
        "key": "conversation_id",
        "observed_types": [
          "string"
        ],
        "purpose": "Conversation-level source identifier."
      },
      {
        "key": "title",
        "observed_types": [
          "string"
        ],
        "purpose": "Sampling/navigation context; do not treat title as a verified topic label."
      },
      {
        "key": "create_time",
        "observed_types": [
          "number"
        ],
        "purpose": "Place conversations in available comparison periods."
      },
      {
        "key": "update_time",
        "observed_types": [
          "number"
        ],
        "purpose": "Record latest activity when selecting dated examples."
      },
      {
        "key": "current_node",
        "observed_types": [
          "string"
        ],
        "purpose": "Retain the conversation's current branch endpoint where relevant."
      }
    ],
    "existing_stage2_inventory_values": [
      {
        "name": "message_count",
        "purpose": "Use the verified per-conversation count when available."
      },
      {
        "name": "size_bytes",
        "purpose": "Use the verified per-conversation byte size when available."
      },
      {
        "name": "character_count",
        "purpose": "Use the verified per-conversation character count when available."
      },
      {
        "name": "message_date_range",
        "purpose": "Use observed message timestamps to choose comparison periods."
      },
      {
        "name": "attachment_availability",
        "purpose": "Flag unavailable attachment payloads and source references."
      },
      {
        "name": "source_reference",
        "purpose": "Keep the source record and message reference needed to reopen evidence."
      }
    ],
    "sample_structure": [
      {
        "key": "mapping",
        "observed_types": [
          "object"
        ],
        "purpose": "Traverse, do not copy the full graph."
      },
      {
        "key": "mapping entry key / node id",
        "observed_types": [
          "dynamic key; verify in source schema"
        ],
        "purpose": "Stable reference for each sampled node."
      },
      {
        "key": "parent",
        "observed_types": [
          "null",
          "string"
        ],
        "purpose": "Preserve branch ancestry."
      },
      {
        "key": "children",
        "observed_types": [
          "array"
        ],
        "purpose": "Preserve alternative replies and branch structure when present."
      },
      {
        "key": "message",
        "observed_types": [
          "null",
          "object"
        ],
        "purpose": "Skip null nodes; inspect message-bearing nodes."
      },
      {
        "key": "message.id",
        "observed_types": [
          "string"
        ],
        "purpose": "Stable message citation reference; retain repeated IDs and distinguish nodes by node reference."
      },
      {
        "key": "message.author.role",
        "observed_types": [
          "string"
        ],
        "purpose": "Attribute user, assistant, and tool messages correctly."
      },
      {
        "key": "message.create_time",
        "observed_types": [
          "number"
        ],
        "purpose": "Order exchanges and distinguish event date from discussion date where available."
      },
      {
        "key": "message.content.parts",
        "observed_types": [
          "array"
        ],
        "purpose": "Read exact source text for sampled conversations only; required to identify question/context types and test passage boundaries."
      }
    ],
    "selected_metadata": [
      {
        "key": "metadata",
        "observed_types": [
          "null",
          "object"
        ],
        "capture": "Only compact citation/source or attachment descriptors needed to reopen or characterize sampled evidence."
      },
