      },
      {
        "key": "content_references",
        "observed_types": [
          "array"
        ],
        "capture": "Only compact citation/source or attachment descriptors needed to reopen or characterize sampled evidence."
      }
    ],
    "sampling_record": [
      {
        "name": "sampled",
        "purpose": "Mark which conversations were actually inspected; do not imply exhaustive coverage."
      },
      {
        "name": "sample_basis",
        "purpose": "Record selection reason/stratum (date, size, branch, topic candidate, or other checklist-relevant criterion)."
      },
      {
        "name": "coverage_status",
        "purpose": "Keep inventoried, searched, read, analyzed, synthesized, and verified states distinct."
      }
    ]
  },
  "later_or_conditional": [
    {
      "key": "default_model_slug",
      "observed_types": [
        "string"
      ],
      "handling": "Retain for the later evolution-of-use comparison if the source record has it."
    },
    {
      "key": "conversation_template_id",
      "observed_types": [
        "null",
        "string"
      ],
      "handling": "Defer unless it is relevant to a selected Stage 3 question."
    },
    {
      "keys": [
        "is_archived",
        "is_do_not_remember",
        "is_read_only",
        "is_starred",
        "is_study_mode",
        "memory_scope",
        "pinned_time",
        "plugin_ids",
        "voice"
