    },
    {
      "name": "outputs",
      "status": "no direct outputs key observed",
      "handling": "Describe only when sample evidence or attachment descriptors support it."
    }
  ],
  "data_handling": {
    "sample_text": "Read exact content.parts values only for selected samples from the conversation shard JSON files listed in source.conversation_shards within source.repository_directory. Do not copy conversation text or quotations into this key-plan file or issue comments.",
    "attachments": "The checklist says omitted attachment payloads remain unavailable; preserve references and mark the limitation rather than inferring contents.",
    "repository_scope": "For Stage 3 sampling, use only the listed files already present in source.repository_directory; do not initiate any external archive handoff."
  },
  "inventory_limitations": [
    "key_type_inventory.json is recursive and flattened; it reports global key/type observations, not JSON paths. Verify paths and scope against the source record before extracting values.",
    "The prior plan was not sufficient by itself for Stage 3 because it omitted message/branch structure and sampled source-content access."
