{
  "$schema": "https://json-schema.bestnameyet.org/stage3/passage-boundary-specification.v1.json",
  "specificationMetadata": {
    "version": "1.0.0",
    "date": "2026-10-17",
    "stage": "Stage 3 Preparation and Pilot Design",
    "author": "BestNameYet StateMachines Gemini Worker",
    "purpose": "Formulate rigorous conversation-to-exchange-to-classification-passage subdivision rules, strict target vs context boundaries, branch path isolation, overlap tracking, and comparative size-model evaluation."
  },
  "unitHierarchy": {
    "description": "Defines the four-tier structural progression from raw conversation archive records to bounded semantic classification passages.",
    "tiers": [
      {
        "level": 1,
        "name": "Conversation",
        "sourceScope": "Root JSON object in shard bins",
        "identifyingKeys": ["id", "conversation_id", "title", "create_time", "update_time", "mapping"],
        "description": "The overarching conversation session container comprising a non-linear tree of mapping nodes."
      },
      {
        "level": 2,
        "name": "Branch Path",
        "sourceScope": "Directed root-to-leaf path through mapping graph",
        "identifyingKeys": ["branchPathId", "rootNodeId", "leafNodeId", "pathLength"],
        "description": "An isolated linear traversal from root to a specific terminal leaf node, resolving tree branch points into distinct analytical trajectories."
      },
      {
        "level": 3,
        "name": "Ordered Turn Exchange",
        "sourceScope": "Consecutive user-assistant turn pair on an active branch path",
        "identifyingKeys": ["exchangeId", "userNodeId", "assistantNodeId", "toolNodeIds"],
        "description": "The atomic conversational functional unit: a user prompt followed by intermediate tool executions and the corresponding assistant response."
      },
      {
        "level": 4,
        "name": "Classification Passage",
        "sourceScope": "Target exchange(s) packaged with isolated preceding and succeeding context windows",
        "identifyingKeys": ["targetPassageId", "targetExchangeIds", "contextBeforeNodeIds", "contextAfterNodeIds"],
        "description": "The operational classification unit submitted to model workers, separating labeled target text from unclassified framing context."
      }
    ]
  },
  "boundaryRules": {
    "exchangeDefinition": {
      "rule": "An exchange is strictly defined as an ordered sequence beginning with a user node (`message.author.role == 'user'`), incorporating any immediately following tool-call or assistant intermediate message nodes, and terminating at the final assistant response node (`message.author.role == 'assistant'`) before the next user prompt or branch termination.",
      "structuralHandling": {
        "nullMessages": "Mapping nodes with null `message` payloads are navigational routing points and must be traversed without creating turn boundaries.",
        "systemNodes": "Initial system instructions or metadata nodes preceding the first user prompt are categorized as conversation preamble metadata, not turn exchanges.",
        "consecutiveSameRole": "If a user submits consecutive messages without an assistant response, they are grouped into a composite user prompt turn within the same exchange."
      }
    },
    "targetDelineation": {
      "rule": "The target passage is the explicit unit of semantic classification and evidentiary labeling. All catalog labels (subject/topic, user purpose, analytical perspective, conversation outcome) must be justified exclusively by source evidence contained within the target passage.",
      "citationStandard": "Every label assigned must carry explicit provenance pointers (`source_file`, `conversation_id`, `node_id`, `message_id`, `char_start`, `char_end_exclusive`) referencing text strictly located within the target passage boundaries."
    },
    "contextBeforeRules": {
      "rule": "`contextBefore` consists of preceding exchanges along the active branch ancestry path, terminating immediately prior to the start of the target passage.",
      "permittedUsage": "Used solely for interpretive disambiguation: pronoun resolution, antecedent conversational constraints, problem setup, and reference frame understanding.",
      "prohibition": "Topics, entities, complaints, or instructions appearing solely in `contextBefore` must never be assigned as labels to the target passage."
    },
    "contextAfterRules": {
      "rule": "`contextAfter` consists of succeeding exchanges along the active branch path, beginning immediately after the target passage termination.",
      "permittedUsage": "Used solely for outcome and reaction analysis: verifying whether the user accepted the response, issued a correction, asked a follow-up, or abruptly switched topics.",
      "prohibition": "Subsequent queries, new topics, or revisions introduced in `contextAfter` must never back-propagate to label the target passage."
    },
    "branchPreservationRules": {
      "rule": "All conversations containing branch forks (`node.children.length > 1`) must be analyzed by partitioning the tree into isolated linear branch paths. Under no circumstances may sibling or alternative replies be concatenated, flattened, or chronologically interleaved into a synthetic sequence.",
      "pathResolution": "Every unique root-to-leaf traversal forms an independent branch path. Shared prefix nodes before the fork are linked by identical node IDs across paths but evaluated within their specific branch context."
    },
    "overlapTrackingMechanism": {
      "rule": "When using sliding passage windows, target exchanges are assigned deterministic identifiers (`targetPassageId` and `targetNodeIds`). Evidence aggregation, frequency counting, and cross-passage synthesis must index observations strictly by `(conversation_id, node_id, message_id)` from target passages.",
      "deduplication": "A turn exchange that appears as `contextBefore` in one passage and as `target` in another passage receives primary evidentiary weight exactly once—under its target manifestation. Context appearances carry zero independent evidence weight."
    }
  },
  "candidatePassageModels": [
    {
      "modelId": "M1",
      "modelName": "Atomic Exchange Unit (1-Exchange Pair)",
      "sizeWindow": "1 User Prompt + 1 Assistant Response (typically 200–800 tokens; 2 conversational turns)",
      "rationale": "Isolates the immediate functional request and response to measure whether topic discovery and classification can operate at minimal conversational granularity without noise from adjacent topics.",
      "advantages": "Eliminates intra-passage topic mixing; provides pinpoint citation accuracy and unambiguous speaker attribution; creates clean mapping boundaries that prevent adjacent discussion drift.",
      "potentialRisks": "Higher vulnerability to contextual insufficiency on short, elliptic, or anaphoric follow-up prompts (e.g., 'why?', 'continue', or pronoun-heavy responses), requiring frequent fallback to contextBefore."
    },
    {
      "modelId": "M2",
      "modelName": "Sliding Triad Window (3-Exchange Sequence)",
      "sizeWindow": "3 Sequential Exchanges: Target centered between 1 preceding and 1 succeeding exchange (~1,200–3,500 tokens; 6 conversational turns)",
      "rationale": "Balances immediate request-reply mechanics with local conversational momentum, capturing immediate clarifications, corrections, and multi-turn explanations within a manageable context window.",
      "advantages": "High contextual sufficiency for iterative tasks, software debugging, and multi-step reasoning; directly captures correction loops (Q2) and immediate assistant assumptions (Q3) in a unified window.",
      "potentialRisks": "Moderate risk of topic mixing across abrupt conversational pivots; requires strict enforcement to ensure workers do not label background turns as target evidence."
    },
    {
      "modelId": "M3",
      "modelName": "Macro Sub-Session (Topical Phase / Multi-Exchange Window)",
      "sizeWindow": "Variable Window of 5 to 10 Sequential Exchanges bounded by detected topic shifts or session pauses (up to 8,000 tokens; 10–20 turns)",
      "rationale": "Evaluates whether macro-level user trajectories, protracted project designs, or extended relationship reflections can be captured holistically as unified episodes.",
      "advantages": "Maximizes contextual sufficiency and thematic coherence for long-horizon goals (Q1) and chronological usage analysis (Q4); avoids artificial fragmentation of extended workflows.",
      "potentialRisks": "Severe topic dilution and keyword mixing; citations become coarse or ambiguous across long transcripts; high risk of conflating distinct conversational shifts into a single generic label."
    }
  ],
  "comparativeEvaluationPlan": {
    "objective": "Empirically determine the optimal passage window size across the representative conversations identified in the Stage 3 pilot.",
    "testSample": [
      "68274338-a4c4-8002-984a-7fb1433a6ea6 (Resonator/Flow Clarification - Tech)",
      "6a3561a1-b18c-83e8-ad7d-653207e557a5 (Thermometer Shopping List - Corrections)",
      "688f0b31-d4f8-8324-8a44-5ea0a101eb84 (Scrum/Sprint Modeling - Procedure)",
      "68956b3c-725c-8322-84e9-f8464220dac8 (Application Letter - Employment/Interpersonal)"
    ],
    "evaluationMetrics": [
      {
        "metric": "Contextual Sufficiency",
        "description": "Percentage of prepared passages that can be accurately labeled without flagging 'insufficient_context'.",
        "targetBenchmark": "Contextual sufficiency >= 90% across sampled domains."
      },
      {
        "metric": "Topic Mixing Risk",
        "description": "Frequency of passages where multiple disparate substantive subjects are compressed into a single target, forcing multiple unrelated topic labels.",
        "targetBenchmark": "Passages requiring > 2 disparate subject labels <= 5%."
      },
      {
        "metric": "Citation Accuracy and Granularity",
        "description": "Precision of character-level and node-level supporting references tied to specific claim elements.",
        "targetBenchmark": "100% of assigned labels grounded in exact target offsets; zero citation hallucination."
      },
      {
        "metric": "Label Consistency",
        "description": "Inter-model agreement when applying consolidated catalog labels across candidate passage sizes.",
        "targetBenchmark": "Stable dominant topic identification across M1 and M2."
      }
    ],
    "executionProtocol": "Extract identical source conversation branches under M1, M2, and M3 representations; run parallel label discovery; compare discovered label specificity, boundary failures, and citation precision; consolidate results into the Stage 3 passage selection decision."
  },
  "dataContract": {
    "passagePayloadStructure": {
      "targetPassageId": "string (e.g., conv-uuid_branch-0_ex-02)",
      "conversationId": "string (source conversation UUID)",
      "branchPathId": "string (root-to-leaf path identifier)",
      "exchangeIndex": "integer (sequential index of exchange along branch)",
      "contextBefore": [
        {
          "nodeId": "string",
          "messageId": "string",
          "role": "string (user | assistant | system | tool)",
          "createTime": "number",
          "text": "string"
        }
      ],
      "targetExchange": {
        "userTurn": {
          "nodeId": "string",
          "messageId": "string",
          "createTime": "number",
          "text": "string"
        },
        "intermediateTurns": [
          {
            "nodeId": "string",
            "messageId": "string",
            "role": "string",
            "text": "string"
          }
        ],
        "assistantTurn": {
          "nodeId": "string",
          "messageId": "string",
          "createTime": "number",
          "text": "string"
        }
      },
      "contextAfter": [
        {
          "nodeId": "string",
          "messageId": "string",
          "role": "string (user | assistant | tool)",
          "createTime": "number",
          "text": "string"
        }
      ]
    }
  }
}

